<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { syncSavedDecksFromAccount, type SavedL12Deck } from '@/l12/decks'
import { connect, enterTournamentMatch, l12State, spectateTournamentMatch } from '@/l12/net'
import { hasPermission, platformState, tournamentApi, type Tournament, type TournamentMatch, type TournamentParticipant } from '@/l12/platform'
import { tournamentDeckVisibilityText, tournamentDisasterModeText, tournamentFormatText, tournamentMatchStatusText, tournamentPhaseText, tournamentResultText, tournamentRoundStatusText, tournamentStatusText } from '@/l12/tournamentLabels'
import { tournamentTimeControlLabel } from '@/l12/tournamentTime'
import TournamentJudgeDesk from './TournamentJudgeDesk.vue'
import TournamentManagementPanel from './TournamentManagementPanel.vue'

type Tab = 'overview'|'schedule'|'standings'|'participants'|'rules'|'judge'|'manage'
const route = useRoute(); const router = useRouter(); const tournament = ref<Tournament | null>(null)
const tab = ref<Tab>('overview'); const loading = ref(true); const busy = ref(false); const notice = ref('')
const deckName = ref(''); const savedDecks = ref<SavedL12Deck[]>([]); const dropArmed = ref(false)
const participantReasons = reactive<Record<string,string>>({}); const matchReasons = reactive<Record<string,string>>({})
const accountId = computed(() => platformState.account?.id || '')
const me = computed(() => tournament.value?.participants.find(item => item.accountId === accountId.value))
const canOrganize = computed(() => !!tournament.value && (tournament.value.organizerAccountId === accountId.value || hasPermission('tournaments.manage')))
const canJudge = computed(() => !!tournament.value && (canOrganize.value || tournament.value.referees.some(item => item.accountId === accountId.value) || hasPermission('tournaments.rulings.write')))
const canViewManage = computed(() => canOrganize.value || tournament.value?.pendingOrganizerTransfer?.toAccountId === accountId.value)
const rounds = computed(() => tournament.value?.rounds || [])

async function load() { loading.value = true; try { tournament.value = await tournamentApi.getByCode(String(route.params.code)); document.title = `${tournament.value.name} · 赛事中心` } catch (error) { notice.value = error instanceof Error ? error.message : '赛事不存在' } finally { loading.value = false } }
async function mutate(work: (item: Tournament) => Promise<Tournament>, success: string) { if (!tournament.value || busy.value) return; busy.value = true; try { tournament.value = await work(tournament.value); notice.value = success } catch (error) { notice.value = error instanceof Error ? error.message : '操作失败' } finally { busy.value = false } }
function register() { void mutate(item => tournamentApi.register(item.id, item.version), '报名成功；牌组将在赛前签到时锁定') }
function drop() { if (!dropArmed.value) { dropArmed.value = true; notice.value = '再次点击确认退出赛事；正式席位释放后会自动递补候补玩家'; return } void mutate(item => tournamentApi.drop(item.id, item.version), '已退出赛事；候补将自动递补') }
function preCheckIn() { void mutate(item => tournamentApi.preCheckIn(item.id, item.version, deckName.value, ''), '牌组快照已锁定，赛前签到完成') }
function remove(person: TournamentParticipant, ban: boolean) { const reason = participantReasons[person.accountId]?.trim(); if (!reason) { notice.value = '请先填写移出或限制理由'; return } void mutate(item => tournamentApi.removeParticipant(item.id, item.version, person.accountId, ban, reason), ban ? '玩家已移出并禁止再次报名' : '玩家已移出') }
function unban(person: TournamentParticipant) { const reason = participantReasons[person.accountId]?.trim(); if (!reason) { notice.value = '请先填写解除禁报名理由'; return } void mutate(item => tournamentApi.setRegistrationBan(item.id, item.version, person.accountId, false, reason), '已解除禁报名') }
function nextRound() { void mutate(item => tournamentApi.nextRound(item.id, item.version, '上一轮赛果已复核'), '下一轮配对已生成') }
function startRound(number: number) { void mutate(item => tournamentApi.startRound(item.id, number, item.version, '本轮签到状态已确认'), `第 ${number} 轮已开始`) }
function pauseRound(number: number, paused: boolean) { void mutate(item => tournamentApi.pauseRound(item.id, number, item.version, !paused, '工作人员控制整轮状态'), !paused ? '本轮已暂停' : '本轮已恢复') }
function pauseMatch(match: TournamentMatch) { const reason = matchReasons[match.id]?.trim(); if (!reason) { notice.value = '请先填写暂停或恢复本桌的理由'; return } void mutate(item => tournamentApi.pauseMatch(item.id, match.id, item.version, !match.paused, reason), match.paused ? '本桌已恢复' : '本桌已暂停') }
function roundCheckIn(roundNumber: number, ready: boolean) { void mutate(item => tournamentApi.checkIn(item.id, roundNumber, item.version, undefined, ready), ready ? '本轮到场已确认' : '已取消本轮到场状态') }
async function room(match: TournamentMatch, spectate: boolean) { if (!tournament.value) return; try { await connect(); spectate ? spectateTournamentMatch(tournament.value.id, match.id) : enterTournamentMatch(tournament.value.id, match.id); await new Promise<void>((resolve, reject) => { const started = Date.now(); const check = () => { if (l12State.game?.tournamentMatchId === match.id || l12State.room?.roomCode === match.roomCode) return resolve(); if (l12State.notice) return reject(new Error(l12State.notice)); if (Date.now() - started > 8_000) return reject(new Error('进入赛事房间超时，请留在本页重试')); window.setTimeout(check, 80) }; check() }); await router.push('/game') } catch (error) { notice.value = error instanceof Error ? error.message : '无法进入房间' } }
async function copyLink() { await navigator.clipboard.writeText(location.href); notice.value = '稳定赛事链接已复制' }
async function exportCsv() { if (!tournament.value) return; try { const blob = await tournamentApi.exportCsv(tournament.value.id); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `tournament-${tournament.value.code}.csv`; link.click(); URL.revokeObjectURL(link.href) } catch (error) { notice.value = error instanceof Error ? error.message : '导出失败' } }
const onResource = () => { void load() }; const onVisibility = () => { if (document.visibilityState === 'visible') void load() }
onMounted(() => { window.addEventListener('l12-resource-tournaments', onResource); document.addEventListener('visibilitychange', onVisibility); void Promise.all([load(), syncSavedDecksFromAccount().then(value => { savedDecks.value = Object.values(value); if (!deckName.value && savedDecks.value.length) deckName.value = savedDecks.value[0].name })]) })
onBeforeUnmount(() => { window.removeEventListener('l12-resource-tournaments', onResource); document.removeEventListener('visibilitychange', onVisibility) })
</script>

<template>
  <main class="detail-page">
    <button class="back" @click="router.push('/battle/tournaments')">← 返回赛事中心</button>
    <p v-if="loading" class="state-panel" role="status">正在加载赛事…</p><p v-else-if="!tournament" class="notice" role="alert">{{ notice }}</p>
    <template v-else>
      <header class="detail-page-head"><div><span class="eyebrow"><small>{{ tournament.code }}</small><i>{{ tournamentStatusText(tournament.status) }}</i><i>{{ tournamentPhaseText(tournament.phase) }}</i></span><h1>{{ tournament.name }}</h1><p>{{ tournament.description || '暂无赛事简介' }}</p></div><div class="header-actions"><button @click="copyLink">复制链接</button><button @click="exportCsv">导出 CSV</button></div></header>
      <aside v-if="tournament.status === 'canceled'" class="alert" role="alert"><b>赛事已取消</b><span>{{ tournament.cancellationReason || '请联系主办者了解详情' }}</span></aside>
      <aside v-else-if="me" class="next"><span class="next-label">YOUR NEXT STEP</span><b>你的下一步</b><span v-if="me.waitlisted">当前候补第 {{ me.waitlistPosition }} 位，正式席位释放后会自动递补。</span><span v-else-if="tournament.status === 'registration' && !me.deck">开赛前请完成签到并锁定牌组。</span><span v-else-if="tournament.status === 'registration'">赛前签到已完成，请等待主办者开赛。</span><span v-else>查看下方赛程，进入自己的桌次。</span></aside>
      <nav class="tabs" aria-label="赛事详情"><button v-for="item in ([['overview','概览'],['schedule','赛程'],['standings','排名'],['participants','参赛者'],['rules','规则'],['judge','裁判台'],...(canViewManage ? [['manage','主办管理']] : [])] as [Tab,string][] )" :key="item[0]" :class="{active: tab === item[0]}" :aria-current="tab === item[0] ? 'page' : undefined" @click="tab=item[0]">{{ item[1] }}</button></nav>
      <p v-if="notice" class="notice" role="status" aria-live="polite">{{ notice }}</p>
      <section v-if="tab === 'overview'" class="panel overview"><p><small>主办者</small><b>{{ tournament.organizerName }}</b></p><p><small>赛制</small><b>{{ tournamentFormatText(tournament.format) }}</b></p><p><small>人数</small><b>{{ tournament.counts.active }}/{{ tournament.maxPlayers }} <span>候补 {{ tournament.counts.waitlisted }}</span></b></p><p><small>计划时间</small><b>{{ tournament.startAt ? new Date(tournament.startAt).toLocaleString('zh-CN') : '待定' }}</b></p><p><small>赛事阶段</small><b>{{ tournamentPhaseText(tournament.phase) }}</b></p><div v-if="tournament.postponements.length" class="wide timeline"><h2>时间变更</h2><p v-for="item in tournament.postponements" :key="item.id"><time>{{ new Date(item.newStartAt).toLocaleString('zh-CN') }}</time><span>{{ item.reason }}</span></p></div><div v-if="tournament.status === 'registration'" class="wide personal"><header><small>PLAYER ACTION</small><h2>参赛操作</h2><p>报名时无需提交牌组；正式席位玩家在赛前签到时锁定。</p></header><div class="personal-actions"><button v-if="!me" class="primary" :disabled="busy || !tournament.registrationOpen" @click="register">{{ tournament.registrationOpen ? '报名（暂不提交牌组）' : '报名已关闭' }}</button><button v-else class="danger" :disabled="busy" @click="drop">{{ dropArmed ? '确认退出赛事' : '退出赛事' }}</button><template v-if="me && !me.waitlisted && !me.deck"><select v-model="deckName" aria-label="选择账号牌组"><option value="" disabled>选择账号牌组</option><option v-for="deck in savedDecks" :key="deck.name" :value="deck.name">{{ deck.name }}</option></select><button class="primary" :disabled="busy || !deckName" @click="preCheckIn">签到并锁定牌组</button><span v-if="!savedDecks.length">账号中暂无可用牌组，请先到牌库创建并保存。</span></template></div></div></section>
      <section v-else-if="tab === 'schedule'" class="panel schedule"><div v-if="!rounds.length" class="empty-state"><b>赛程尚未生成</b><span>主办者完成开赛检查后，这里会显示轮次与桌次。</span></div><article v-for="round in rounds" :key="round.id" class="round"><header><div><small>ROUND {{ round.number }}</small><h2>第 {{ round.number }} 轮</h2><span>{{ tournamentRoundStatusText(round.status) }}<i v-if="round.paused">整轮已暂停</i></span></div><div v-if="canJudge" class="round-actions"><button v-if="round.status !== 'running' && round.status !== 'completed'" @click="startRound(round.number)">开始本轮</button><button v-if="round.status === 'running'" @click="pauseRound(round.number, round.paused)">{{ round.paused ? '恢复整轮' : '暂停整轮' }}</button><button v-if="round.status === 'completed' && tournament.status === 'running'" class="primary" @click="nextRound">生成下一轮</button></div></header><div class="match-list"><article v-for="match in round.matches" :key="match.id" class="match"><div class="match-table"><small>TABLE</small><b>第 {{ match.table }} 桌</b></div><div class="match-players"><b>{{ match.playerAName }} <span>对</span> {{ match.playerBName }}</b><span>{{ match.result ? tournamentResultText(match.result) : tournamentMatchStatusText(match.status) }}<em v-if="match.paused">已暂停：{{ match.pauseReason }}</em></span></div><div class="match-actions"><button v-if="match.playerAAccountId === accountId && !match.readyA && round.status === 'checkin'" class="primary" @click="roundCheckIn(round.number,true)">本轮签到</button><button v-if="match.playerBAccountId === accountId && !match.readyB && round.status === 'checkin'" class="primary" @click="roundCheckIn(round.number,true)">本轮签到</button><button v-if="match.canEnter" class="primary" @click="room(match,false)">进入对局</button><button v-if="match.canSpectate" @click="room(match,true)">观战</button><template v-if="canJudge && match.status === 'running'"><input v-model.trim="matchReasons[match.id]" aria-label="暂停或恢复理由" placeholder="暂停或恢复理由"><button @click="pauseMatch(match)">{{ match.paused ? '恢复本桌' : '暂停本桌' }}</button></template></div></article></div></article></section>
      <section v-else-if="tab === 'standings'" class="panel standings"><div class="section-title"><small>STANDINGS</small><h2>赛事排名</h2></div><div class="standings-table"><div class="thead"><span>名次</span><span>玩家</span><span>胜-负-平</span><span>对手分</span></div><article v-for="item in tournament.finalSwissStandings.length ? tournament.finalSwissStandings : rounds.at(-1)?.standings || []" :key="item.accountId"><b data-label="名次">#{{ item.rank }}</b><strong data-label="玩家">{{ item.username }}</strong><span data-label="胜-负-平">{{ item.wins }}-{{ item.losses }}-{{ item.draws }}</span><span data-label="对手分">{{ item.opponentScore }}</span></article><div v-if="!(tournament.finalSwissStandings.length || rounds.at(-1)?.standings?.length)" class="empty-state"><b>排名尚未产生</b><span>完成轮次后会在这里显示权威排名。</span></div></div></section>
      <section v-else-if="tab === 'participants'" class="panel participants"><div class="section-title"><small>PARTICIPANTS</small><h2>参赛者与候补</h2><p>主办者可在赛前和赛中移出玩家，并决定是否禁止其再次报名。</p></div><article v-for="person in tournament.participants" :key="person.accountId" class="person"><div class="person-info"><b>{{ person.username }}</b><span class="person-tags"><small v-if="person.waitlisted">候补 {{ person.waitlistPosition }}</small><small v-else-if="person.deck">已锁定牌组</small><small v-if="person.removed">已移出</small><small v-if="person.registrationBanned">禁止再次报名</small></span></div><div v-if="canOrganize && person.accountId !== tournament.organizerAccountId" class="person-actions"><label><span>操作理由</span><input v-model.trim="participantReasons[person.accountId]" placeholder="仅工作人员可见"></label><button v-if="!person.removed" @click="remove(person,false)">移出</button><button v-if="!person.removed" class="danger" @click="remove(person,true)">移出并禁报名</button><button v-if="person.registrationBanned" @click="unban(person)">解除禁报名</button></div></article></section>
      <section v-else-if="tab === 'rules'" class="panel rules"><div class="rule-grid"><p><small>规则版本</small><b>{{ tournament.rules.ruleset }}</b></p><p><small>牌组公开</small><b>{{ tournamentDeckVisibilityText(tournament.rules.deckVisibility) }}</b></p><p><small>天灾范围</small><b>{{ tournamentDisasterModeText(tournament.rules.disasterMode) }}</b></p><p><small>计时规范</small><b>{{ tournamentTimeControlLabel(tournament.timeControl) }}</b></p></div><div class="rule-details"><article><h2>天灾卡池</h2><p>{{ tournament.rules.disasterCardIds.join('、') || '使用规则版本默认卡池' }}</p></article><article><h2>构筑限制</h2><p v-for="item in tournament.rules.cardRestrictions" :key="`${item.cardId}-${item.maxCopies}`">{{ item.cardId }}：最多 {{ item.maxCopies }} 张</p><p v-if="!tournament.rules.cardRestrictions.length">无额外构筑限制</p></article></div></section>
      <section v-else-if="tab === 'judge'" class="panel"><TournamentJudgeDesk :tournament="tournament" :can-judge="canJudge" @updated="value => tournament = value" @notice="value => notice = value" /></section>
      <section v-else-if="tab === 'manage'" class="panel"><TournamentManagementPanel :tournament="tournament" :account-id="accountId" :can-organize="canOrganize" @updated="value => tournament = value" @notice="value => notice = value" /></section>
    </template>
  </main>
</template>

<style scoped>
.detail-page{box-sizing:border-box;max-width:1320px;margin:0 auto;padding:24px clamp(18px,3vw,42px) 64px;display:grid;gap:16px;font-family:'Microsoft YaHei','微软雅黑',sans-serif;color:var(--l12-ui-text)}.detail-page button{min-height:40px;padding:0 13px;border:1px solid var(--l12-ui-line-strong);border-radius:var(--l12-ui-radius-sm);background:var(--l12-ui-control);color:var(--l12-ui-text-soft);font-weight:800;cursor:pointer}.detail-page button:disabled{cursor:not-allowed;opacity:.45}.back{justify-self:start;border-color:transparent!important;background:transparent!important;color:var(--l12-ui-info)!important;padding-left:0!important}.detail-page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;padding-bottom:18px;border-bottom:1px solid var(--l12-ui-line)}.detail-page-head h1{margin:7px 0;font-size:clamp(26px,3vw,36px);line-height:1.18}.detail-page-head p{max-width:760px;margin:0;color:var(--l12-ui-text-muted);font-size:14px}.eyebrow{display:flex;align-items:center;flex-wrap:wrap;gap:7px}.eyebrow small,.section-title small,.round header small,.personal header small{color:var(--l12-ui-info);font:900 11px ui-monospace,monospace;letter-spacing:.14em}.eyebrow i{padding:4px 7px;border:1px solid var(--l12-ui-line-strong);border-radius:999px;background:var(--l12-ui-control);color:var(--l12-ui-text-soft);font-size:11px;font-style:normal;font-weight:800}.header-actions{display:flex;flex:0 0 auto;gap:8px}.alert,.next{padding:14px 16px;border:1px solid var(--l12-ui-line);border-radius:var(--l12-ui-radius-sm)}.alert{display:grid;gap:4px;border-left:3px solid var(--l12-ui-danger);background:#281218}.alert span{color:#efb1b7;font-size:13px}.next{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:4px 16px;border-left:3px solid var(--l12-ui-accent);background:linear-gradient(90deg,#25200f,var(--l12-ui-panel))}.next-label{grid-row:1/3;color:var(--l12-ui-accent);font:900 11px ui-monospace,monospace;letter-spacing:.12em}.next>b{font-size:14px